// Layer 1 — the shape (Lesson 3)
interface User {
  readonly id: number;
  email: string;
  role: "admin" | "user";
  displayName?: string;
}

// Layer 2 — the runtime guard (Lesson 5): proof the compiler can consume
function isUser(value: unknown): value is User {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "number" &&
    typeof v.email === "string" &&
    (v.role === "admin" || v.role === "user") &&
    (v.displayName === undefined || typeof v.displayName === "string")
  );
}

// Layer 3 — the typed fetch wrapper (Lessons 4 & 6): never trusts, always checks
async function getJson<T>(
  url: string,
  guard: (value: unknown) => value is T
): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) {
    throw new ApiError(res.status, await safeErrorBody(res));
  }
  const body: unknown = await res.json();   // unknown at the boundary
  if (!guard(body)) {
    throw new Error(`Unexpected payload from ${url}`);
  }
  return body;   // T — earned, not wished
}

