interface Post {
  readonly id: number;
  title: string;
  tags: string[];
}

function isPost(value: unknown): value is Post {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "number" &&
    typeof v.title === "string" &&
    Array.isArray(v.tags) &&
    v.tags.every((t) => typeof t === "string")
  );
}

function isPosts(value: unknown): value is Post[] {
  return Array.isArray(value) && value.every(isPost);
}

async function fetchPosts(url: string): Promise<Post[]> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status} from ${url}`);
  const body: unknown = await res.json();
  if (!isPosts(body)) throw new Error(`Unexpected posts payload from ${url}`);
  return body;
}
